const RAW_EXERCISES = [
  { id: "Pushups", name: "Push-Up", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "Builds pushing strength in the chest, shoulders and triceps while your core works overtime to keep your body straight — a genuine full-body move disguised as an arm exercise. Great for everyday pushing tasks like getting up off the floor or pushing open a heavy door.", instructions: ["Lie face down, place hands about shoulder-width apart, and push up so your torso is held at arms' length above the floor.", "Lower your body until your chest almost touches the floor, inhaling as you go.", "Push back up to the starting position, exhaling and squeezing your chest at the top.", "Keep your body in a straight line from head to heels throughout — don't let your hips sag or pike up."], images: ["images/Pushups_0.webp", "images/Pushups_1.webp"] },
  { id: "Bodyweight_Squat", name: "Bodyweight Squat", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["quadriceps"], secondaryMuscles: ["glutes", "hamstrings"], benefit: "Strengthens the quads, glutes and hamstrings and reinforces the hip-and-knee bending pattern you use every time you sit down, stand up, or pick something off the floor. One of the best exercises for building functional lower-body strength before adding weight.", instructions: ["Stand with feet shoulder-width apart, chest up, arms out in front for balance.", "Push your hips back and bend your knees to lower down, as if sitting into a chair.", "Go down until your thighs are about parallel to the floor, keeping your heels planted.", "Drive through your heels to stand back up to the starting position."], images: ["images/Bodyweight_Squat_0.webp", "images/Bodyweight_Squat_1.webp"] },
  { id: "Bodyweight_Walking_Lunge", name: "Walking Lunge", location: "home", level: "beginner", equipment: "none", primaryMuscles: ["quadriceps"], secondaryMuscles: ["glutes", "hamstrings"], benefit: "Trains each leg independently, which exposes and corrects left-right strength imbalances that squats can hide. Builds quad, glute and hamstring strength while also challenging balance and hip stability — carries over directly to walking, climbing stairs and running.", instructions: ["Stand tall and take a controlled step forward with one leg.", "Lower your hips until both knees are bent around 90 degrees — front knee over the ankle, back knee hovering just above the floor.", "Push off the front foot to bring your back leg forward into the next lunge.", "Keep your torso upright and core braced as you alternate legs, walking forward."], images: ["images/Bodyweight_Walking_Lunge_0.webp", "images/Bodyweight_Walking_Lunge_1.webp"] },
  { id: "Plank", name: "Plank", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["abdominals"], secondaryMuscles: ["lower back"], benefit: "Builds deep core endurance — the abdominals, lower back and shoulders all work together to resist your hips sagging or piking. A strong plank translates into a more stable spine for lifting, running and almost every other exercise on this list.", instructions: ["Get into a push-up position, then bend your elbows and rest your weight on your forearms.", "Form a straight line from your shoulders to your ankles — don't let your hips sag or rise.", "Keep your neck neutral, brace your core, and breathe steadily.", "Hold the position, starting with 20-30 seconds and building up over time."], images: ["images/Plank_0.webp", "images/Plank_1.webp"] },
  { id: "Crunches", name: "Crunch", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["abdominals"], secondaryMuscles: [], benefit: "Isolates the abdominals to build strength and definition through the midsection. A simple entry point into core training, though it works the abs through a shorter range than moves like planks, so it's best paired with other core work rather than used alone.", instructions: ["Lie on your back with knees bent and feet flat on the floor.", "Place your hands lightly behind your head or crossed on your chest.", "Curl your shoulders up off the floor by contracting your abs, exhaling as you rise.", "Lower back down slowly with control — avoid pulling on your neck."], images: ["images/Crunches_0.webp", "images/Crunches_1.webp"] },
  { id: "Mountain_Climbers", name: "Mountain Climbers", location: "home", level: "beginner", equipment: "none", primaryMuscles: ["quadriceps"], secondaryMuscles: ["abdominals", "shoulders"], benefit: "A cardio-and-core combo move: it raises your heart rate quickly while your abs and shoulders stabilize your body against the fast leg drive. Useful for building conditioning and core control at the same time, especially in a home workout with no equipment.", instructions: ["Start in a push-up position with arms fully extended and core tight.", "Drive one knee toward your chest, keeping your hands planted and hips low.", "Quickly switch legs, extending the first leg back as the other knee drives in.", "Keep a steady, controlled rhythm — this is a cardio and core move, not a race."], images: ["images/Mountain_Climbers_0.webp", "images/Mountain_Climbers_1.webp"] },
  { id: "Superman", name: "Superman", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["lower back"], secondaryMuscles: ["glutes"], benefit: "Strengthens the lower back and glutes — muscles that are easy to neglect but critical for posture and protecting your spine during squats, deadlifts, and everyday bending and lifting. A good counterbalance to ab-focused exercises like crunches.", instructions: ["Lie face down with arms extended in front of you and legs straight.", "Simultaneously lift your arms, chest, and legs off the floor at the same time.", "Hold the raised position briefly, squeezing your lower back and glutes.", "Lower back down with control and repeat."], images: ["images/Superman_0.webp", "images/Superman_1.webp"] },
  { id: "Russian_Twist", name: "Russian Twist", location: "home", level: "intermediate", equipment: "body only", primaryMuscles: ["abdominals"], secondaryMuscles: [], benefit: "Targets the obliques (the sides of your core), building rotational strength that carries over to twisting movements in sport and daily life, like swinging a bat or turning to grab something behind you.", instructions: ["Sit on the floor with knees bent, leaning your torso back slightly to engage your core.", "Lift your feet slightly off the ground if you can, keeping your back straight.", "Rotate your torso to tap the floor on one side, then the other, in a controlled twisting motion.", "Keep the movement coming from your core, not just your arms."], images: ["images/Russian_Twist_0.webp", "images/Russian_Twist_1.webp"] },
  { id: "Bench_Dips", name: "Bench Dips (Chair Dips)", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["triceps"], secondaryMuscles: ["shoulders"], benefit: "Isolates the triceps for pushing strength and arm definition, using nothing but a chair or bench. A useful accessory to push-ups since it hits the triceps harder while the chest does less of the work.", instructions: ["Sit on the edge of a sturdy chair or bench, hands gripping the edge beside your hips.", "Walk your feet forward and slide off the edge so your weight is supported by your arms.", "Bend your elbows to lower your body straight down, keeping elbows pointing backward.", "Push through your palms to straighten your arms and return to the top."], images: ["images/Bench_Dips_0.webp", "images/Bench_Dips_1.webp"] },
  { id: "Single_Leg_Glute_Bridge", name: "Single-Leg Glute Bridge", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["glutes"], secondaryMuscles: ["hamstrings"], benefit: "Builds glute and hamstring strength on one leg at a time, which improves hip stability and helps correct imbalances between sides. Strong glutes support the lower back and knees during squats, lunges and running.", instructions: ["Lie on your back with knees bent, feet flat on the floor.", "Extend one leg straight out and keep the other foot planted.", "Push through the planted heel to lift your hips up, squeezing your glutes at the top.", "Lower with control, keeping your hips level, then repeat before switching legs."], images: ["images/Single_Leg_Glute_Bridge_0.webp", "images/Single_Leg_Glute_Bridge_1.webp"] },
  { id: "Step-up_with_Knee_Raise", name: "Step-Up with Knee Raise", location: "home", level: "beginner", equipment: "body only", primaryMuscles: ["glutes"], secondaryMuscles: ["quadriceps"], benefit: "Trains single-leg strength and balance the way stairs and hiking do in real life, while the knee raise at the top adds a hip-flexor and coordination challenge. A low-impact way to build leg strength and cardio capacity together.", instructions: ["Stand facing a sturdy step, box, or low stool.", "Step up fully with one foot, pressing through the heel to stand on the platform.", "As you stand, drive the opposite knee up toward your chest for balance and control.", "Step back down with control and repeat, alternating legs."], images: ["images/Step-up_with_Knee_Raise_0.webp", "images/Step-up_with_Knee_Raise_1.webp"] },
  { id: "Barbell_Bench_Press_-_Medium_Grip", name: "Barbell Bench Press", location: "gym", level: "beginner", equipment: "barbell", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "The classic strength builder for the chest, shoulders and triceps, and one of the clearest ways to track upper-body pushing strength over time as you add weight to the bar.", instructions: ["Lie on a flat bench, feet flat on the floor, and grip the bar slightly wider than shoulder-width.", "Unrack the bar and hold it straight above your chest with arms extended.", "Lower the bar slowly to your mid-chest, keeping elbows at roughly a 45-degree angle.", "Press the bar back up to the starting position, exhaling as you push."], images: ["images/Barbell_Bench_Press_-_Medium_Grip_0.webp", "images/Barbell_Bench_Press_-_Medium_Grip_1.webp"] },
  { id: "Barbell_Squat", name: "Barbell Back Squat", location: "gym", level: "beginner", equipment: "barbell", primaryMuscles: ["quadriceps"], secondaryMuscles: ["glutes", "hamstrings"], benefit: "The foundation lift for lower-body strength — loads the quads, glutes and hamstrings under a heavier weight than bodyweight training allows, while also demanding core bracing and hip mobility. Builds strength that carries into nearly every sport and daily movement.", instructions: ["Set the bar on a rack at shoulder height and position it across your upper back.", "Step back, feet shoulder-width apart, and brace your core.", "Bend your knees and hips to squat down until your thighs are at least parallel to the floor.", "Drive through your heels to stand back up, keeping your chest up throughout."], images: ["images/Barbell_Squat_0.webp", "images/Barbell_Squat_1.webp"] },
  { id: "Barbell_Deadlift", name: "Barbell Deadlift", location: "gym", level: "intermediate", equipment: "barbell", primaryMuscles: ["lower back"], secondaryMuscles: ["hamstrings", "glutes"], benefit: "Works the entire posterior chain — lower back, glutes and hamstrings — in a single lift, and closely mirrors the real-world mechanics of picking something heavy off the ground safely. One of the best overall strength builders, but form matters most here of any lift on this list.", instructions: ["Stand with feet hip-width apart, bar over the middle of your feet.", "Bend at the hips and knees to grip the bar just outside your legs, back flat.", "Drive through your heels and extend your hips and knees together to stand up, keeping the bar close to your body.", "Lock out tall at the top, then reverse the motion with control to lower the bar back down."], images: ["images/Barbell_Deadlift_0.webp", "images/Barbell_Deadlift_1.webp"] },
  { id: "Wide-Grip_Lat_Pulldown", name: "Wide-Grip Lat Pulldown", location: "gym", level: "beginner", equipment: "cable", primaryMuscles: ["lats"], secondaryMuscles: ["biceps"], benefit: "Builds width and strength in the back (lats) and biceps using a pulling motion, which balances out all the pushing work from bench presses and shoulder presses. A good entry point for beginners not yet ready for pull-ups.", instructions: ["Sit at the lat pulldown machine and grip the bar wider than shoulder-width.", "Lean back very slightly and pull the bar down to your upper chest, leading with your elbows.", "Squeeze your shoulder blades together at the bottom of the movement.", "Slowly let the bar rise back up to full arm extension with control."], images: ["images/Wide-Grip_Lat_Pulldown_0.webp", "images/Wide-Grip_Lat_Pulldown_1.webp"] },
  { id: "Seated_Cable_Rows", name: "Seated Cable Row", location: "gym", level: "beginner", equipment: "cable", primaryMuscles: ["middle back"], secondaryMuscles: ["biceps", "lats"], benefit: "Strengthens the middle back and biceps with a horizontal pulling motion, which improves posture and helps offset the forward-hunching many people develop from sitting and screen use.", instructions: ["Sit at the cable row station with knees slightly bent, feet on the platform.", "Grip the handle and sit up tall with a straight back.", "Pull the handle toward your torso, squeezing your shoulder blades together.", "Extend your arms back out slowly, keeping your torso still and back straight."], images: ["images/Seated_Cable_Rows_0.webp", "images/Seated_Cable_Rows_1.webp"] },
  { id: "Dumbbell_Shoulder_Press", name: "Dumbbell Shoulder Press", location: "gym", level: "intermediate", equipment: "dumbbell", primaryMuscles: ["shoulders"], secondaryMuscles: ["triceps"], benefit: "Builds pressing strength and size in the shoulders, with the triceps assisting — dumbbells also force each arm to stabilize independently, which builds more balanced shoulder strength than a barbell version.", instructions: ["Sit or stand holding a dumbbell in each hand at shoulder height, palms facing forward.", "Brace your core and press the dumbbells straight overhead until your arms are extended.", "Pause briefly at the top without locking your elbows harshly.", "Lower the dumbbells back to shoulder height with control."], images: ["images/Dumbbell_Shoulder_Press_0.webp", "images/Dumbbell_Shoulder_Press_1.webp"] },
  { id: "Dumbbell_Bicep_Curl", name: "Dumbbell Bicep Curl", location: "gym", level: "beginner", equipment: "dumbbell", primaryMuscles: ["biceps"], secondaryMuscles: ["forearms"], benefit: "Isolates the biceps for arm strength and size. Mostly a cosmetic and accessory move rather than a functional necessity, but a satisfying, low-injury-risk way to build arm strength alongside bigger compound lifts.", instructions: ["Stand tall holding a dumbbell in each hand, arms extended, palms facing forward.", "Keeping your elbows pinned to your sides, curl the dumbbells up toward your shoulders.", "Squeeze your biceps at the top of the movement.", "Lower the dumbbells back down slowly and under control."], images: ["images/Dumbbell_Bicep_Curl_0.webp", "images/Dumbbell_Bicep_Curl_1.webp"] },
  { id: "Triceps_Pushdown", name: "Triceps Pushdown", location: "gym", level: "beginner", equipment: "cable", primaryMuscles: ["triceps"], secondaryMuscles: [], benefit: "Isolates the triceps, which make up most of your upper arm and do a lot of the work in every pressing exercise. A good accessory move to build extra pushing strength beyond what bench and shoulder presses alone provide.", instructions: ["Stand facing a cable machine with a bar or rope attachment set at the top.", "Grip the attachment with elbows tucked close to your sides.", "Push the attachment down until your arms are fully extended, keeping elbows stationary.", "Slowly let it rise back up to the starting position, resisting the pull."], images: ["images/Triceps_Pushdown_0.webp", "images/Triceps_Pushdown_1.webp"] },
  { id: "Leg_Press", name: "Leg Press", location: "gym", level: "beginner", equipment: "machine", primaryMuscles: ["quadriceps"], secondaryMuscles: ["glutes", "hamstrings"], benefit: "Loads the quads, glutes and hamstrings similarly to a squat but with the machine supporting your balance and back, which makes it a good option for beginners building leg strength before progressing to free-weight squats.", instructions: ["Sit in the leg press machine with feet shoulder-width apart on the platform.", "Release the safety locks and lower the platform by bending your knees toward your chest.", "Stop when your knees reach about a 90-degree angle.", "Press through your heels to extend your legs back to the starting position, without locking your knees."], images: ["images/Leg_Press_0.webp", "images/Leg_Press_1.webp"] },
  { id: "Leg_Extensions", name: "Leg Extension", location: "gym", level: "beginner", equipment: "machine", primaryMuscles: ["quadriceps"], secondaryMuscles: [], benefit: "Isolates the quadriceps specifically, which is useful for building targeted strength or size, or for rehabbing a weak knee under the guidance of a professional — though it doesn't build the same overall functional strength as squats.", instructions: ["Sit in the leg extension machine with the pad resting on your lower shins.", "Grip the side handles and keep your back flat against the seat.", "Extend your legs to lift the pad up until your legs are straight.", "Lower back down slowly with control, without letting the weight stack slam."], images: ["images/Leg_Extensions_0.webp", "images/Leg_Extensions_1.webp"] },
  { id: "Lying_Leg_Curls", name: "Lying Leg Curl", location: "gym", level: "beginner", equipment: "machine", primaryMuscles: ["hamstrings"], secondaryMuscles: [], benefit: "Isolates the hamstrings, the muscles on the back of your thigh that are easy to under-train since most beginner leg exercises emphasize the quads. Balanced hamstring strength helps protect the knees.", instructions: ["Lie face down on the leg curl machine with the pad resting just above your heels.", "Grip the handles for stability and keep your hips pressed into the bench.", "Curl your legs up by bringing your heels toward your glutes.", "Lower back down slowly with control to the starting position."], images: ["images/Lying_Leg_Curls_0.webp", "images/Lying_Leg_Curls_1.webp"] },
  { id: "Dumbbell_Lunges", name: "Dumbbell Lunge", location: "gym", level: "beginner", equipment: "dumbbell", primaryMuscles: ["quadriceps"], secondaryMuscles: ["glutes", "hamstrings"], benefit: "Adds load to the walking lunge pattern, building single-leg quad, glute and hamstring strength along with balance — a strong step between bodyweight lunges and heavier barbell leg work.", instructions: ["Stand tall holding a dumbbell in each hand at your sides.", "Step forward with one leg and lower your hips until both knees are bent near 90 degrees.", "Keep your front knee over your ankle and your torso upright.", "Push back through the front heel to return to standing, then repeat on the other leg."], images: ["images/Dumbbell_Lunges_0.webp", "images/Dumbbell_Lunges_1.webp"] },
  { id: "Pullups", name: "Pull-Up", location: "home", level: "intermediate", equipment: "pull-up bar", primaryMuscles: ["lats"], secondaryMuscles: ["biceps", "middle back"], benefit: "The gold-standard bodyweight back builder — trains the lats and biceps through a full range of motion using nothing but your own weight. Strong pull-ups build the upper-back strength that protects your shoulders and posture, and they're a genuine milestone most beginners work years toward.", instructions: ["Grip a pull-up bar with hands facing away from you, just wider than shoulder-width.", "Hang with arms fully extended, core braced, and a slight arch in your lower back.", "Pull your chest up toward the bar by driving your elbows down and back, not by yanking with your arms.", "Lower yourself back down under control until your arms are fully straight, then repeat."], images: ["images/Pullups_0.webp", "images/Pullups_1.webp"] },
  { id: "Chin-Up", name: "Chin-Up", location: "home", level: "intermediate", equipment: "pull-up bar", primaryMuscles: ["lats"], secondaryMuscles: ["biceps", "forearms", "middle back"], benefit: "A close cousin of the pull-up that shifts more of the load onto the biceps while still building serious back strength. A great option to rotate in if your biceps are lagging behind your back on regular pull-ups.", instructions: ["Grip the bar with palms facing toward you, hands closer than shoulder-width.", "Hang with arms fully extended and torso straight.", "Pull yourself up by driving your elbows down, focusing on squeezing your biceps as your chin clears the bar.", "Lower back down slowly and with control to full arm extension, then repeat."], images: ["images/Chin-Up_0.webp", "images/Chin-Up_1.webp"] },
  { id: "Decline_Push-Up", name: "Decline Push-Up", location: "home", level: "intermediate", equipment: "bench or box", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "Raising your feet shifts more bodyweight onto your upper chest and shoulders than a standard push-up, making it a natural next step once regular push-ups feel easy. Builds upper-chest strength without needing a gym.", instructions: ["Get into push-up position with your feet elevated on a bench, box, or sturdy step.", "Keep your hands roughly shoulder-width apart and your body in a straight line from head to heels.", "Lower your chest toward the floor with control, keeping elbows at about 45 degrees.", "Push back up to full extension, squeezing your chest at the top."], images: ["images/Decline_Push-Up_0.webp", "images/Decline_Push-Up_1.webp"] },
  { id: "Plyo_Push-up", name: "Plyo Push-Up", location: "home", level: "advanced", equipment: "none", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "Builds explosive, power-oriented chest and shoulder strength on top of the muscle you already built from regular push-ups. Useful for anyone chasing athletic power rather than just strength, but only take this on once strict push-ups feel easy and controlled.", instructions: ["Start in a standard push-up position with your body in a straight line.", "Lower your chest toward the floor under control, just like a normal push-up.", "Explosively push up hard enough that your hands leave the ground.", "Land softly with bent elbows to absorb the impact, reset, and repeat."], images: ["images/Plyo_Push-up_0.webp", "images/Plyo_Push-up_1.webp"] },
  { id: "Hanging_Leg_Raise", name: "Hanging Leg Raise", location: "home", level: "advanced", equipment: "pull-up bar", primaryMuscles: ["abdominals"], secondaryMuscles: [], benefit: "One of the toughest true tests of core strength, since it trains the abs to control your entire lower body against gravity with no assistance. Far more demanding than floor-based ab work like crunches — a genuine advanced-level move.", instructions: ["Hang from a pull-up bar with arms fully extended and legs straight down.", "Brace your core and tilt your pelvis slightly backward before you start moving.", "Raise your legs until your torso and legs form roughly a 90-degree angle, exhaling as you lift.", "Lower your legs back down slowly and under control — resist the urge to swing."], images: ["images/Hanging_Leg_Raise_0.webp", "images/Hanging_Leg_Raise_1.webp"] },
  { id: "Freehand_Jump_Squat", name: "Jump Squat", location: "home", level: "intermediate", equipment: "none", primaryMuscles: ["quadriceps"], secondaryMuscles: ["calves", "glutes", "hamstrings"], benefit: "Turns the basic bodyweight squat into a power and conditioning move, training your legs to produce force quickly rather than just under a steady load. Good for building athletic explosiveness once regular squats are easy.", instructions: ["Stand with feet shoulder-width apart and arms crossed over your chest or swinging naturally.", "Lower into a squat until your thighs are close to parallel with the floor.", "Explode upward through your heels and jump as high as you comfortably can.", "Land softly with bent knees to absorb the impact and immediately flow into the next rep."], images: ["images/Freehand_Jump_Squat_0.webp", "images/Freehand_Jump_Squat_1.webp"] },
  { id: "Bent_Over_Barbell_Row", name: "Bent-Over Barbell Row", location: "gym", level: "intermediate", equipment: "barbell", primaryMuscles: ["middle back"], secondaryMuscles: ["biceps", "lats", "shoulders"], benefit: "Builds thick, dense middle-back strength using a heavier load than most cable or machine rows allow. Strong rows balance out all the pressing work from bench presses and build the back strength that supports good posture.", instructions: ["Hold a barbell with an overhand grip and hinge forward at the hips until your torso is close to parallel with the floor, knees slightly bent.", "Let the bar hang directly below your shoulders with your arms straight — this is the starting position.", "Pull the bar up toward your lower ribs, keeping your elbows close to your body and squeezing your shoulder blades together.", "Lower the bar back down under control to full arm extension, keeping your back flat throughout."], images: ["images/Bent_Over_Barbell_Row_0.webp", "images/Bent_Over_Barbell_Row_1.webp"] },
  { id: "Barbell_Incline_Bench_Press_-_Medium_Grip", name: "Incline Barbell Bench Press", location: "gym", level: "intermediate", equipment: "barbell", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "Shifts more of the work onto the upper chest and front shoulders than a flat bench press, filling in a part of the chest that's easy to under-develop if incline pressing is skipped.", instructions: ["Lie back on an incline bench set to roughly 30-45 degrees and grip the bar slightly wider than shoulder-width.", "Unrack the bar and hold it straight over your upper chest with arms extended.", "Lower the bar slowly until it lightly touches your upper chest.", "Press the bar back up to the starting position, driving through your upper chest and shoulders."], images: ["images/Barbell_Incline_Bench_Press_-_Medium_Grip_0.webp", "images/Barbell_Incline_Bench_Press_-_Medium_Grip_1.webp"] },
  { id: "Romanian_Deadlift", name: "Romanian Deadlift", location: "gym", level: "intermediate", equipment: "barbell", primaryMuscles: ["hamstrings"], secondaryMuscles: ["calves", "glutes", "lower back"], benefit: "Specifically targets the hamstrings and glutes through a hip-hinge pattern, which is the same movement you use to pick things up safely. A key exercise for balancing out all the quad-dominant work from squats and lunges, and for building resilient hamstrings that resist strains.", instructions: ["Hold a barbell in front of your thighs with an overhand grip, feet hip-width apart.", "With a slight bend in your knees, push your hips back and lower the bar down the front of your legs, keeping your back flat.", "Lower until you feel a strong stretch in your hamstrings — usually around shin height — without rounding your back.", "Drive your hips forward to stand back up, squeezing your glutes and hamstrings at the top."], images: ["images/Romanian_Deadlift_0.webp", "images/Romanian_Deadlift_1.webp"] },
  { id: "Barbell_Hip_Thrust", name: "Barbell Hip Thrust", location: "gym", level: "intermediate", equipment: "barbell", primaryMuscles: ["glutes"], secondaryMuscles: ["calves", "hamstrings"], benefit: "One of the most effective exercises for building glute strength — research shows it activates the glutes even more than squats do, because it loads them right at full hip extension, the point where they're strongest. Strong glutes support the lower back and knees and improve performance in every other lower-body lift.", instructions: ["Sit on the ground with your upper back against a bench and a padded barbell rolled over your hips.", "Plant your feet flat on the floor, roughly shoulder-width apart, knees bent.", "Drive through your heels to lift your hips up until your torso is roughly parallel to the floor, squeezing your glutes hard at the top.", "Lower your hips back down under control without letting the bar rest on the floor between reps."], images: ["images/Barbell_Hip_Thrust_0.webp", "images/Barbell_Hip_Thrust_1.webp"] },
  { id: "Face_Pull", name: "Face Pull", location: "gym", level: "intermediate", equipment: "cable", primaryMuscles: ["shoulders"], secondaryMuscles: ["middle back"], benefit: "Targets the rear shoulders and upper back — muscles that heavy pressing work tends to neglect. A small-weight, high-value move for shoulder health, since it directly counteracts the rounded-forward posture that comes from too much bench pressing and desk time.", instructions: ["Set a rope attachment on a cable machine at roughly head height.", "Grip the rope with both hands, palms facing each other, and step back so the cable is taut.", "Pull the rope toward your face, flaring your elbows out and pulling the ends of the rope apart as they reach your face.", "Squeeze your shoulder blades together at the peak, then return to the start under control."], images: ["images/Face_Pull_0.webp", "images/Face_Pull_1.webp"] },
  { id: "EZ-Bar_Skullcrusher", name: "EZ-Bar Skullcrusher", location: "gym", level: "intermediate", equipment: "e-z curl bar", primaryMuscles: ["triceps"], secondaryMuscles: ["forearms"], benefit: "Isolates the triceps hard, which make up roughly two-thirds of your upper arm and drive a lot of your pressing strength. A strong triceps accessory to pair with bench press or incline press work.", instructions: ["Lie on a flat bench holding an EZ-bar with a close grip, arms extended straight up over your chest.", "Keeping your upper arms still, bend your elbows to lower the bar toward your forehead.", "Pause just above your forehead once you feel a stretch in your triceps.", "Extend your elbows to press the bar back to the starting position."], images: ["images/EZ-Bar_Skullcrusher_0.webp", "images/EZ-Bar_Skullcrusher_1.webp"] },
  { id: "Hack_Squat", name: "Hack Squat (Machine)", location: "gym", level: "intermediate", equipment: "machine", primaryMuscles: ["quadriceps"], secondaryMuscles: ["calves", "glutes", "hamstrings"], benefit: "Loads the quads heavily while the machine supports your back and balance, which lets you push closer to your limit safely than a free-weight squat allows. A strong option for building quad size and strength once basic squats are well established.", instructions: ["Position your back against the pad of the hack squat machine with shoulders under the shoulder pads.", "Set your feet shoulder-width apart on the platform and release the safety handles.", "Bend your knees to lower the platform until your thighs are just past parallel to the floor, keeping your knees tracking over your toes.", "Press through your heels to extend your legs back to the starting position, without locking your knees."], images: ["images/Hack_Squat_0.webp", "images/Hack_Squat_1.webp"] },
  { id: "Dips_-_Chest_Version", name: "Chest Dips", location: "gym", level: "advanced", equipment: "parallel bars", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "A demanding bodyweight-plus-gravity pressing move that builds the lower chest and triceps harder than most push-up variations can. Because it loads your full bodyweight through a long range of motion, it's best attempted once you have solid push-up and bench press strength already.", instructions: ["Grip parallel bars and press up to support your body with arms fully extended.", "Lean your torso forward slightly and let your elbows flare out a little as you lower yourself.", "Descend until you feel a solid stretch across your chest.", "Push back up to the starting position, squeezing your chest at the top."], images: ["images/Dips_-_Chest_Version_0.webp", "images/Dips_-_Chest_Version_1.webp"] },
  { id: "Standing_Calf_Raise", name: "Standing Calf Raise", location: "gym", level: "beginner", equipment: "machine", primaryMuscles: ["calves"], secondaryMuscles: [], benefit: "Directly targets the calves, a muscle group that barely gets worked by squats, presses or rows. Strong calves support ankle stability for running, jumping and every lower-body lift, and they're easy to neglect if you never train them on purpose.", instructions: ["Position your shoulders under the pads with the balls of your feet on the platform and heels hanging off.", "Stand tall with knees slightly soft, not locked, as your starting position.", "Rise up onto your toes as high as possible, squeezing your calves hard at the top.", "Lower your heels back down under control until you feel a full stretch, then repeat."], images: ["images/Standing_Calf_Raise_0.webp", "images/Standing_Calf_Raise_1.webp"] },
  { id: "Barbell_Shrug", name: "Barbell Shrug", location: "gym", level: "beginner", equipment: "barbell", primaryMuscles: ["traps"], secondaryMuscles: [], benefit: "Isolates the trapezius, the muscle across the top of your shoulders that gives a back real width and thickness and that rows and pulldowns only train indirectly. Strong traps also help stabilize the shoulder girdle during heavy pulling and pressing.", instructions: ["Stand tall holding a barbell in front of your thighs with an overhand grip, feet shoulder-width apart.", "Keeping your arms straight, elevate your shoulders straight up toward your ears as high as you can.", "Hold the contraction for a second at the top, avoiding any rolling motion.", "Lower back down under control to the starting position and repeat."], images: ["images/Barbell_Shrug_0.webp", "images/Barbell_Shrug_1.webp"] },
  { id: "Side_Lateral_Raise", name: "Side Lateral Raise", location: "gym", level: "beginner", equipment: "dumbbell", primaryMuscles: ["shoulders"], secondaryMuscles: [], benefit: "Isolates the side delts, the part of the shoulder that gives it width and roundness but gets little direct work from pressing movements alone. A key accessory move for balanced, injury-resistant shoulders.", instructions: ["Stand holding a dumbbell in each hand at your sides, torso upright, with a slight bend in the elbows.", "Keeping that elbow bend fixed, raise both arms out to the sides until they're roughly parallel to the floor.", "Pause briefly at the top, leading with your elbows rather than your hands.", "Lower back down slowly to the starting position and repeat."], images: ["images/Side_Lateral_Raise_0.webp", "images/Side_Lateral_Raise_1.webp"] },
  { id: "Standing_Military_Press", name: "Standing Barbell Overhead Press", location: "gym", level: "intermediate", equipment: "barbell", primaryMuscles: ["shoulders"], secondaryMuscles: ["triceps"], benefit: "A compound overhead press that builds serious shoulder and triceps strength while forcing your core and glutes to brace to keep you upright — a genuine full-body strength test, not just a shoulder exercise. Complements horizontal pressing like bench press by training strength overhead.", instructions: ["Set a barbell at about chest height on a rack and grip it just outside shoulder width.", "Un-rack the bar onto your front shoulders, step back, and stand with feet shoulder-width apart.", "Press the bar straight overhead until your arms are fully locked out, keeping your core braced.", "Lower the bar back down to your shoulders under control and repeat."], images: ["images/Standing_Military_Press_0.webp", "images/Standing_Military_Press_1.webp"] },
  { id: "Barbell_Curl", name: "Barbell Curl", location: "gym", level: "beginner", equipment: "barbell", primaryMuscles: ["biceps"], secondaryMuscles: ["forearms"], benefit: "A classic biceps builder that lets you load more weight than dumbbell curls alone, adding a second angle of attack for arm strength and size beyond what a single curl variation provides.", instructions: ["Stand tall holding a barbell with an underhand, shoulder-width grip, elbows tucked to your sides.", "Keeping your upper arms stationary, curl the bar up by contracting your biceps.", "Squeeze hard at the top once the bar reaches shoulder height.", "Lower the bar back down under control to the starting position and repeat."], images: ["images/Barbell_Curl_0.webp", "images/Barbell_Curl_1.webp"] },
  { id: "Farmers_Walk", name: "Farmer's Walk", location: "gym", level: "intermediate", equipment: "dumbbell", primaryMuscles: ["forearms"], secondaryMuscles: ["abdominals", "glutes", "hamstrings", "lower back", "quadriceps", "traps"], benefit: "Builds crushing grip strength and forearm endurance while your core, traps and legs all work isometrically to keep you upright under load — one exercise that trains carrying capacity for real-world lifting and hauling.", instructions: ["Pick up a heavy dumbbell in each hand and stand tall, shoulders back, core braced.", "Walk forward with short, controlled steps for a set distance or time, breathing steadily.", "Keep your grip tight and avoid letting your shoulders round forward or your torso lean.", "Set the weights down with control at the end of the walk, rather than dropping them."], images: ["images/Farmers_Walk_0.webp", "images/Farmers_Walk_1.webp"] },
  { id: "Standing_Cable_Wood_Chop", name: "Standing Cable Wood Chop", location: "gym", level: "beginner", equipment: "cable", primaryMuscles: ["abdominals"], secondaryMuscles: ["shoulders"], benefit: "Trains the obliques and core through a rotational pattern, unlike crunches or planks which only train the abs to resist flexion or extension. Rotational core strength carries over to swinging, throwing and twisting movements in sport and daily life.", instructions: ["Set a cable to the highest pulley position and stand side-on to the machine, arm's length away.", "Grip the handle with both hands, arms extended, so the cable pulls diagonally across your body.", "Pull the handle down and across your body toward your opposite knee, rotating through your torso.", "Return slowly and with control to the starting position, then repeat before switching sides."], images: ["images/Standing_Cable_Wood_Chop_0.webp", "images/Standing_Cable_Wood_Chop_1.webp"] },
  { id: "Band_Back_Flyes", name: "Band Back Flye", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["shoulders"], secondaryMuscles: ["middle back", "triceps"], benefit: "Targets the rear delts with a pulling motion that's easy to load precisely with a band. A key move for balanced, healthy shoulders since rear delts get little work from pressing exercises.", instructions: ["Run a band around a stationary post like that of a squat rack.", "Grab the band by the handles and stand back so that the tension in the band rises.", "Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.", "As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.", "After a pause, go back to the original position as you inhale.", "Repeat for the recommended amount of repetitions."], images: ["images/Band_Back_Flyes_0.webp", "images/Band_Back_Flyes_1.webp"] },
  { id: "Band_External_Rotation", name: "Band External Rotation", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["shoulders"], secondaryMuscles: [], benefit: "Isolates the rotator cuff muscles that stabilize the shoulder joint but rarely get trained directly. Cheap insurance against shoulder injury, especially if you do a lot of pressing work.", instructions: ["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.", "Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.", "With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.", "Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.", "Continue as far as you are able, pause, and then return to the starting position."], images: ["images/Band_External_Rotation_0.webp", "images/Band_External_Rotation_1.webp"] },
  { id: "Band_Internal_Rotation", name: "Band Internal Rotation", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["shoulders"], secondaryMuscles: [], benefit: "The counterpart to external rotation \u2014 strengthens the front of the rotator cuff for balanced shoulder stability. Often paired with external rotation as a shoulder-health superset.", instructions: ["Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.", "Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.", "With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.", "Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.", "Continue as far as you are able, pause, and then return to the starting position."], images: ["images/Band_Internal_Rotation_0.webp", "images/Band_Internal_Rotation_1.webp"] },
  { id: "Band_Lateral_Raise", name: "Band Lateral Raise", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["shoulders"], secondaryMuscles: [], benefit: "Builds width in the side delts with constant band tension through the whole range, unlike a dumbbell raise where tension drops off at the top. A simple, joint-friendly shoulder isolation move.", instructions: ["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.", "Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.", "Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."], images: ["images/Band_Lateral_Raise_0.webp", "images/Band_Lateral_Raise_1.webp"] },
  { id: "Band_Shoulder_Press", name: "Band Shoulder Press", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["shoulders"], secondaryMuscles: ["triceps"], benefit: "A standing overhead press using band resistance, which increases as you press higher \u2014 right when your shoulders are strongest. Builds pressing strength anywhere you can anchor a band underfoot.", instructions: ["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles and lift them so that the hands are at shoulder height at each side.", "Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.", "As you exhale, lift the handles up until your arms are fully extended overhead."], images: ["images/Band_Shoulder_Press_0.webp", "images/Band_Shoulder_Press_1.webp"] },
  { id: "Band_Pull_Apart", name: "Band Pull-Apart", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["shoulders"], secondaryMuscles: ["middle back", "traps"], benefit: "A simple but highly effective move for rear-delt and upper-back health, directly counteracting the forward-rounded posture that comes from desk work and pressing exercises.", instructions: ["Begin with your arms extended straight out in front of you, holding the band with both hands.", "Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.", "Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.", "Pause as you complete the movement, returning to the starting position under control."], images: ["images/Band_Pull_Apart_0.webp", "images/Band_Pull_Apart_1.webp"] },
  { id: "Band_Bench_Press", name: "Band Bench Press", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["chest"], secondaryMuscles: ["shoulders", "triceps"], benefit: "Mimics a bench press pattern using band resistance, with tension increasing through the press \u2014 useful for building pressing strength and speed off the chest without any equipment beyond a band.", instructions: ["Using a flat bench secure a band under the leg of the bench that is nearest to your head.", "Once the band is secure, grab it by both handles and lie down on the bench.", "Extend your arms so that you are holding the band handles in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.", "As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions of your training program."], images: ["images/Band_Bench_Press_0.webp", "images/Band_Bench_Press_1.webp"] },
  { id: "Band_Cross_Over", name: "Band Cross-Over Fly", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["chest"], secondaryMuscles: ["biceps", "shoulders"], benefit: "A standing chest fly using a band anchored behind you, keeping constant tension on the chest through the full range \u2014 something a dumbbell fly can't do at the top of the movement.", instructions: ["Secure an exercise band around a stationary post.", "While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band.", "Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter \"T\") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position.", "While keeping your arms straight, bring them across your chest in a semicircular motion to the front as you exhale and flex your pecs. Hold the contraction for a second.", "Slowly return to the starting position as you inhale.", "Perform for the recommended amount of repetitions."], images: ["images/Band_Cross_Over_0.webp", "images/Band_Cross_Over_1.webp"] },
  { id: "Band_Skull_Crusher", name: "Band Skull Crusher", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["triceps"], secondaryMuscles: [], benefit: "Isolates the triceps through an overhead extension pattern, with the band providing smooth, joint-friendly resistance through the full range of motion.", instructions: ["Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head.", "Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position.", "Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position."], images: ["images/Band_Skull_Crusher_0.webp", "images/Band_Skull_Crusher_1.webp"] },
  { id: "Band_Overhead_Triceps_Extension", name: "Band Overhead Triceps Extension", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["triceps"], secondaryMuscles: [], benefit: "A fast-tempo overhead triceps extension that builds both strength and speed in the triceps, useful for anyone chasing more explosive pressing power.", instructions: ["For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band.", "To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position.", "To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place.", "Pause, and then return to the starting position."], images: ["images/Band_Overhead_Triceps_Extension_0.webp", "images/Band_Overhead_Triceps_Extension_1.webp"] },
  { id: "Band_Upright_Row", name: "Band Upright Row", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["traps"], secondaryMuscles: ["shoulders"], benefit: "Targets the traps and shoulders with a vertical pulling motion. A good accessory move for upper-back and shoulder width using nothing but a band underfoot.", instructions: ["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.", "Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.", "Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.", "Repeat for the recommended amount of repetitions."], images: ["images/Band_Upright_Row_0.webp", "images/Band_Upright_Row_1.webp"] },
  { id: "Band_Assisted_Pull_Up", name: "Band Assisted Pull-Up", location: "bands", level: "advanced", equipment: "bands", primaryMuscles: ["lats"], secondaryMuscles: ["abdominals", "forearms", "middle back"], benefit: "Uses a looped band to offload some of your bodyweight, letting you practice the full pull-up motion with control while you build toward doing them unassisted.", instructions: ["Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance.", "Pull the end of the band down, and place one bent knee into the loop, ensuring it won't slip out. Take a medium to wide grip on the bar. This will be your starting position.", "Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movements.", "After a brief pause, return to the starting position."], images: ["images/Band_Assisted_Pull_Up_0.webp", "images/Band_Assisted_Pull_Up_1.webp"] },
  { id: "Band_Good_Morning", name: "Band Good Morning", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["hamstrings"], secondaryMuscles: ["glutes", "lower back"], benefit: "Trains the hip-hinge pattern and builds hamstring and lower-back strength using a band looped under your feet and across your shoulders \u2014 a safe way to groove the deadlift pattern anywhere.", instructions: ["Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.", "Keeping your legs straight, extend through the hips to come to a near vertical position.", "Ensure that you do not round your back as you go down back to the starting position."], images: ["images/Band_Good_Morning_0.webp", "images/Band_Good_Morning_1.webp"] },
  { id: "Band_Good_Morning_Pull_Through", name: "Band Good Morning Pull-Through", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["hamstrings"], secondaryMuscles: ["glutes", "lower back"], benefit: "A hip-hinge variation that pulls the band from between your legs, emphasizing the glutes and hamstrings through a slightly different angle than the standard good morning.", instructions: ["Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.", "Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.", "Return to the starting position be driving through with the hips to come back to a standing position."], images: ["images/Band_Good_Morning_Pull_Through_0.webp", "images/Band_Good_Morning_Pull_Through_1.webp"] },
  { id: "Seated_Band_Hamstring_Curl", name: "Seated Band Hamstring Curl", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["hamstrings"], secondaryMuscles: [], benefit: "Isolates the hamstrings in a seated position with a band anchored in front of you \u2014 a simple way to train the back of the leg without any machines.", instructions: ["Secure a band close to the ground and place a bench a couple feet away from it.", "Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position.", "Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor.", "Pause at the completion of the movement, and then slowly return to the starting position."], images: ["images/Seated_Band_Hamstring_Curl_0.webp", "images/Seated_Band_Hamstring_Curl_1.webp"] },
  { id: "Band_Squat", name: "Band Squat", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["quadriceps"], secondaryMuscles: ["calves", "glutes", "hamstrings", "lower back"], benefit: "Adds resistance to the bodyweight squat pattern using a band underfoot, with tension increasing as you stand \u2014 right when your legs are strongest. A great way to make squats progressively harder without weights.", instructions: ["To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.", "When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.", "Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.", "Use the heel of your feet to push your body up to the starting position as you exhale.", "Repeat for the recommended amount of repetitions."], images: ["images/Band_Squat_0.webp", "images/Band_Squat_1.webp"] },
  { id: "Band_Hip_Flexion", name: "Band Hip Flexion", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["quadriceps"], secondaryMuscles: [], benefit: "Isolates the hip flexors, the muscles that lift your knee toward your chest \u2014 useful for runners, hikers and anyone wanting stronger, more resilient hips.", instructions: ["Secure one end of the band to the lower portion of a post and attach the other to one ankle.", "Face away from the attachment point of the band.", "Keeping your head and your chest up, raise your knee up to 90 degrees and pause.", "Return the leg to the starting position."], images: ["images/Band_Hip_Flexion_0.webp", "images/Band_Hip_Flexion_1.webp"] },
  { id: "Band_Calf_Raise", name: "Band Calf Raise", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["calves"], secondaryMuscles: [], benefit: "Adds resistance to the standing calf raise using a band, targeting a muscle group that's easy to neglect without a machine or added load.", instructions: ["Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.", "While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.", "Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.", "After a one second contraction, slowly go back down to the starting position.", "Repeat for the recommended amount of repetitions."], images: ["images/Band_Calf_Raise_0.webp", "images/Band_Calf_Raise_1.webp"] },
  { id: "Band_Hip_Adduction", name: "Band Hip Adduction", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["adductors"], secondaryMuscles: [], benefit: "Targets the inner-thigh adductors, muscles that stabilize the knee and hip during lateral movement but are often skipped in standard leg training.", instructions: ["Anchor a band around a solid post or other object.", "Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.", "Stand up straight and hold onto the post if needed. This will be your starting position.", "Keeping the knee straight, raise your right legs out to the side as far as you can.", "Return to the starting position and repeat for the desired rep count.", "Switch sides."], images: ["images/Band_Hip_Adduction_0.webp", "images/Band_Hip_Adduction_1.webp"] },
  { id: "Band_Monster_Walk", name: "Band Monster Walk", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["abductors"], secondaryMuscles: [], benefit: "A lateral walking drill with a band around the ankles or knees that fires up the glutes and hip abductors \u2014 a staple warm-up and strengthening move for knee and hip stability.", instructions: ["Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart.", "To begin, take short steps forward alternating your left and right foot.", "After several steps, do just the opposite and walk backward to where you started."], images: ["images/Band_Monster_Walk_0.webp", "images/Band_Monster_Walk_1.webp"] },
  { id: "Band_Hip_Extension", name: "Band Hip Extension", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["glutes"], secondaryMuscles: ["hamstrings"], benefit: "Builds glute strength through hip extension with a band anchored low and looped around the ankle \u2014 a simple, effective way to train the glutes standing up, no bench required.", instructions: ["Secure one end of the band to the lower portion of a post and attach the other to one ankle.", "Facing the attachment point of the band, hold on to the column to stabilize yourself.", "Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.", "Return the leg to the starting position."], images: ["images/Band_Hip_Extension_0.webp", "images/Band_Hip_Extension_1.webp"] },
  { id: "Band_Hip_Lift", name: "Band Hip Lift", location: "bands", level: "beginner", equipment: "bands", primaryMuscles: ["glutes"], secondaryMuscles: ["calves", "hamstrings"], benefit: "A glute bridge variation with a band across the hips, adding resistance right at the top of the movement where the glutes are working hardest.", instructions: ["After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn't have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won't move.", "Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.", "Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.", "Pause at the top of the motion, and return to the starting position."], images: ["images/Band_Hip_Lift_0.webp", "images/Band_Hip_Lift_1.webp"] },
  { id: "Band_Weighted_Sit_Up", name: "Weighted Band Sit-Up", location: "bands", level: "intermediate", equipment: "bands", primaryMuscles: ["abdominals"], secondaryMuscles: [], benefit: "Adds band resistance to the classic sit-up, forcing the abs to work against tension through the entire range rather than just against bodyweight.", instructions: ["Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them.", "Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain stationary throughout the exercise. This is the starting position.", "Move your torso upward until your upper body is perpendicular to the floor while exhaling. Hold the contraction for a second and lower your upper body back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."], images: ["images/Band_Weighted_Sit_Up_0.webp", "images/Band_Weighted_Sit_Up_1.webp"] },
];

function categoryFromMuscles(m){
  if(m.some(x=>['chest'].includes(x))) return 'Chest';
  if(m.some(x=>['shoulders'].includes(x))) return 'Shoulders';
  if(m.some(x=>['biceps','triceps','forearms'].includes(x))) return 'Arms';
  if(m.some(x=>['lats','middle back','lower back','traps'].includes(x))) return 'Back';
  if(m.some(x=>['abdominals','obliques'].includes(x))) return 'Core';
  if(m.some(x=>['quadriceps','hamstrings','calves','glutes','adductors','abductors'].includes(x))) return 'Legs';
  return null;
}
// The PRIMARY muscle worked determines the exercise's category — a move
// stays "Core" even if a secondary muscle (like lower back on a plank)
// would otherwise match an earlier category in the priority list.
function categoryFrom(e){
  const primary=(e.primaryMuscles||[]).map(x=>x.toLowerCase());
  const secondary=(e.secondaryMuscles||[]).map(x=>x.toLowerCase());
  return categoryFromMuscles(primary) || categoryFromMuscles(secondary) || 'Full Body';
}

// Exercises that are best performed for time/duration rather than a rep count
// (isometric holds and loaded carries).
const TIME_BASED = new Set(['Plank', 'Farmers_Walk']);
// Explosive / high-heart-rate movements — trained more like conditioning work
// than a strict strength lift.
const CARDIO_MOVES = new Set(['Mountain_Climbers', 'Freehand_Jump_Squat', 'Plyo_Push-up', 'Band_Monster_Walk']);
// Heavy compound barbell/machine lifts — trained for fewer reps with longer
// rest than accessory or isolation work.
const HEAVY_COMPOUND = new Set([
  'Barbell_Squat', 'Barbell_Deadlift', 'Barbell_Bench_Press_-_Medium_Grip',
  'Barbell_Incline_Bench_Press_-_Medium_Grip', 'Hack_Squat',
  'Bent_Over_Barbell_Row', 'Leg_Press'
]);

function typeFrom(e, cat){
  if (CARDIO_MOVES.has(e.id)) return 'Cardio';
  if (cat === 'Core') return 'Core & Stability';
  return 'Strength';
}

function schemeFrom(e){
  if (TIME_BASED.has(e.id)) return '3 rounds · 30–45 sec hold · 45 sec rest';
  if (CARDIO_MOVES.has(e.id)) return '3 rounds · 12–15 reps · 45 sec rest';
  if (HEAVY_COMPOUND.has(e.id)) return '4 sets · 5–8 reps · 90 sec rest';
  return '3 sets · 8–12 reps · 60 sec rest';
}

const titleCase = s => String(s||'').replace(/\b\w/g,c=>c.toUpperCase());
const LOCATION_ORDER = ['home','gym','bands'];
const LOCATION_LABELS = { home: 'Home', gym: 'Gym', bands: 'Bands' };
const LOCATION_ICONS = { home: '⌂', gym: '▣', bands: '➰' };
// Some entries use "none" and others "body only" for the exact same
// no-equipment-needed movements — normalize to one consistent label.
const EQUIPMENT_ALIASES = { none: 'body only' };
const EXERCISES = RAW_EXERCISES.map(e => {
  const cat = categoryFrom(e);
  return {
    ...e,
    cat,
    type: typeFrom(e, cat),
    scheme: schemeFrom(e),
    level: titleCase(e.level),
    equipment: titleCase(EQUIPMENT_ALIASES[e.equipment] || e.equipment),
    muscles: [...(e.primaryMuscles||[]), ...(e.secondaryMuscles||[])].map(titleCase).join(' · ') || 'Full body',
    steps: e.instructions || [],
    tips: e.benefit || 'Perform each repetition with control and a comfortable range of motion.',
    loc: e.location,
    locLabel: LOCATION_LABELS[e.location] || titleCase(e.location)
  };
});

const EXERCISE_COUNT = EXERCISES.length;
